-- Agreed tests (verification step 2, plain SQL on PostgreSQL) for AdventureWorks2025 HumanResources.vEmployeeDepartmentHistory.
-- GENERATED by npm run agreed-tests -- --object HumanResources.vEmployeeDepartmentHistory. Do not edit by hand: change the fixed cases
-- in the object's spec, recapture, and review tests/AdventureWorks2025/HumanResources.vEmployeeDepartmentHistory.expected.json.
-- Expected results were captured from the original T-SQL on SQL Server and are reviewed at step 5.
-- Row order is not asserted here (multiset comparison); step 3 checks order where the source guarantees one.
-- Prerequisites: the spec's tables created and the final conversion deployed.
-- Each case is one transaction and always rolls back.

-- @case 1: ended and open histories both listed (EndDate NULL kept); missing shift or person dropped; 1753-01-01 to 9999-12-31; Title '' kept, not NULL
BEGIN;
DELETE FROM humanresources.department;
DELETE FROM humanresources.employee;
DELETE FROM humanresources.employee_department_history;
DELETE FROM humanresources.shift;
DELETE FROM person.person;
INSERT INTO humanresources.department ("DepartmentID", "Name", "GroupName") VALUES
  ('1', 'Engineering', 'Research and Development'),
  ('2', 'Sales', 'Sales and Marketing');
INSERT INTO humanresources.employee ("BusinessEntityID") VALUES
  ('1'),
  ('2'),
  ('3');
INSERT INTO humanresources.employee_department_history ("BusinessEntityID", "DepartmentID", "ShiftID", "StartDate", "EndDate") VALUES
  ('1', '1', '1', '2001-01-01', '2005-06-30'),
  ('1', '2', '2', '2005-07-01', NULL),
  ('2', '1', '3', '2003-03-03', NULL),
  ('2', '2', '1', '1753-01-01', '9999-12-31'),
  ('3', '1', '1', '2004-04-04', NULL);
INSERT INTO humanresources.shift ("ShiftID", "Name") VALUES
  ('1', 'Day'),
  ('2', 'Evening');
INSERT INTO person.person ("BusinessEntityID", "Title", "FirstName", "MiddleName", "LastName", "Suffix") VALUES
  ('1', NULL, 'Ann', NULL, 'Lee', NULL),
  ('2', '', 'Bo', 'J', 'Ng', 'Jr.');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM humanresources.v_employee_department_history;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'Shift', 'Department', 'GroupName', 'StartDate', 'EndDate']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 ended and open histories both listed (EndDate NULL kept); missing shift or person dropped; 1753-01-01…', got, ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'Shift', 'Department', 'GroupName', 'StartDate', 'EndDate']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', NULL, 'Ann', NULL, 'Lee', NULL, 'Day', 'Engineering', 'Research and Development', '2001-01-01', '2005-06-30'),
  ('1', NULL, 'Ann', NULL, 'Lee', NULL, 'Evening', 'Sales', 'Sales and Marketing', '2005-07-01', NULL),
  ('2', '', 'Bo', 'J', 'Ng', 'Jr.', 'Day', 'Sales', 'Sales and Marketing', '1753-01-01', '9999-12-31');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 ended and open histories both listed (EndDate NULL kept); missing shift or person dropped; 1753-01-01…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
